fn fib(n: i32) -> i32 {
    if n < 2 { n } else { fib(n - 1) + fib(n - 2) }
}

fn frame(t: i32) {
    host::display::clear(0x000000);
    host::display::draw_string(8, 6, "FIB", 0x808080, 2);
    let mut i: i32 = 0;
    while i < 13 {
        host::display::draw_number(8, 30 + i * 14, fib(i), 0x00ffcc, 1);
        i = i + 1;
    }
    host::display::present();
}
